    r = t_mixed(); acc = acc + r; printf("t_mixed: %d\n", r);
    r = t_negate(); acc = acc + r; printf("t_negate: %d\n", r);
    r = t_abs_diff(); acc = acc + r; printf("t_abs_diff: %d\n", r);
    r = t_clamp(); acc = acc + r; printf("t_clamp: %d\n", r);
    r = t_fact(); acc = acc + r; printf("t_fact: %d\n", r);
    r = t_fib(); acc = acc + r; printf("t_fib: %d\n", r);
    r = t_gcd(); acc = acc + r; printf("t_gcd: %d\n", r);
    r = t_sum_to(); acc = acc + r; printf("t_sum_to: %d\n", r);
    r = t_power(); acc = acc + r; printf("t_power: %d\n", r);
    r = t_sum_digits(); acc = acc + r; printf("t_sum_digits: %d\n", r);
    r = t_is_positive(); acc = acc + r; printf("t_is_positive: %d\n", r);
