import std::mem;

// std_arena_reset.jhyy — std::arena 的 `arena_reset` 越界回归(W-222)
//
// ⚠️ **这个用例必须待在「没有本地 arena.jhyy」的目录里**。
//   `import arena;` 的查找顺序是「main 文件旁边 → std lib 目录」⇒
//   放在 `compiler/tests/examples/arena_test/` 旁边的话,命中的是那份
//   **本地副本**(`compiler/tests/examples/arena_test/arena.jhyy` —— 编译器
//   自用 arena 的旧翻译)⇒ 根本碰不到 `compiler/src0/std/arena.jhyy`。
//   ⇒ W-222 就是这么活下来的:std::arena **一行测试都没有**。
//   (下面调 `ARENA_SIZE()` 也是同一个用意:它是 std 那份**独有**的函数,
//    解析到别处就会编译失败 —— 目录摆错的话,这个用例自己就红了。)
//
// 复现的 bug(W-222):三个函数对「块有多大」各说各话 ——
//   arena_new_block 按「本次要的量」malloc(旧:8 + size);
//   arena_reset 却按 `def_size`(默认块大小,这里 4MB)摆 end;
//   ⇒ reset 之后的 end 越过块尾 4MB,而真实块只有几十字节
//   ⇒ 随后的分配**写穿块尾踩坏堆** ⇒ 进程 abort(退出码 != 0)。
//
// 现在:块大小 = max(def_size, 本次要的量),并且记在块头的 payload_size 里;
// reset 从块头读回真实大小 ⇒ end 永远落在块内 ✓。
//
// 断言:整块写一遍 + 抽查三个字节读回 ⇒ 写穿的话这一步就把堆踩坏了。
//
// EXPECT: 0
// EXPECT-OUT: "arena reset ok"

import std::arena;

extern fn printf(fmt: *u8, val: i32) -> i32;
extern fn memset(p: *u8, val: i32, n: i64) -> *u8;

// 4MB —— 旧实现下,reset 之后的 end 会被摆到 4MB 处,而真实块只有几十字节。

fn main_jhyy() -> i32 {
    let block: i64 = 4194304 as i64;
    let mut a: Arena = Arena {
        start: 0 as *u8,
        cur: 0 as *u8,
        end: 0 as *u8,
        blocks: 0 as *u8,
        def_size: 0 as i64,
    };
    // std 那份独有的函数 —— 解析到别的 arena 就会编译失败(见文件头注释)。
    if ARENA_SIZE() != (40 as i64) {
        return 1;
    }
    arena_init(&a, block);

    // 先做一次小分配:建块。
    let p = arena_alloc(&a, 8);
    if p == (0 as *u8) {
        return 2;
    }

    // reset:cur 回到块首。
    arena_reset(&a);

    // reset 之后再要一大块 —— 必须是**块内**的地址。
    // 旧实现:fake end = data + 4MB ⇒ 这一块「装得下」⇒ 返回块首
    // ⇒ 下面的 memset 写穿块尾 ⇒ 踩坏堆 ⇒ 进程 abort。
    let want: i64 = block - (64 as i64);
    let q = arena_calloc(&a, want);
    if q == (0 as *u8) {
        return 3;
    }

    // 整块写一遍 —— 写穿的话,堆当场就坏了。
    memset(q, 90 as i32, want);

    // 抽查三个字节读回(首 / 中 / 尾)。
    let mut sum: i64 = 0;
    sum = sum + (*(ptr_add(q, 0 as i64) as *u8) as i64);
    sum = sum + (*(ptr_add(q, want / (2 as i64)) as *u8) as i64);
    sum = sum + (*(ptr_add(q, want - (1 as i64)) as *u8) as i64);
    if sum != (270 as i64) {
        printf("bad sum %d\n", sum as i32);
        return 4;
    }

    // 释放:堆若已被写坏,free 这一步通常也会炸。
    arena_free(&a);

    printf("arena reset ok\n", 0);
    return 0;
}

// conv_test.jhyy — v2.11.19 Phase 5 验证 6 个 user-reachable conversion op
//
// EXPECT: 63
//
// 触发机制:JHYY spec 不允许 `as` int↔float cast,但 fn call 时允许
// call-site type coerce (codegen cg_coerce 走 src_qt != dst_qt 时 emit 转换 op)。
// 每个 fn 把参数当返回值返回,让 caller 在 call site 触发 coerce。
//
// 覆盖:
//   §1 dtosi  — f64 → i32 (return f64 to i32 var)         IL: dtosi
//   §2 stosi  — f32 → i32 (return f32 to i32 var)         IL: stosi
//   §3 truncd — f64 → f32 (return f64 to f32 var)         IL: truncd
//   §4 exts   — f32 → f64 (pass f32 arg to f64 param)     IL: exts (S→D)
//   §5 sltof  — i64 → f64 (return i64 to f64 var)         IL: sltof
//   §6 swtof  — i32 → f64 (return i32 to f64 var)         IL: swtof
//
// 注:ultof/uwtof (u64/u32 → f32) 当前在 user-facing path 不可达
//   (spec 5.6 禁止 int→float `as` cast; cg_coerce 仅在 dst=D 时 emit sltof/swtof;
//   dst=S 且 src=L/W 的路径没有 user construct 触发)。仍 emit 在 dispatch table
//   防御未来 spec 改动 + Phase 2 已验 self-backend 编译通过 (没有 regression)。

fn id_f64(x: f64) -> f64 { return x; }     // §1/§3/§5 caller 走 f64 路径
fn id_f32(x: f32) -> f32 { return x; }     // §2 caller 走 f32 路径
fn id_i32(x: i32) -> i32 { return x; }     // §6 caller 走 i32 路径
fn take_d(x: f64) -> f64 { return x; }     // §4 caller 用 f64 param 接 f32 arg → exts

fn main_jhyy() -> i32 {
    // §1 dtosi: f64 → i32
    let v1: f64 = id_f64(3.7);
    let r1: i32 = v1 as i32;            // dtosi  → 3

    // §2 stosi: f32 → i32
    let v2: f32 = id_f32(3.7);
    let r2: i32 = v2 as i32;            // stosi  → 3

    // §3 truncd: f64 → f32 (via fn return coerce)
    let v3: f64 = id_f64(2.5);
    let r3: f32 = v3 as f32;            // truncd → 2.5f32

    // §4 exts: f32 → f64 (call-site arg coerce)
    let v4_f32: f32 = id_f32(2.5);
    let v4: f64 = take_d(v4_f32);       // exts   — pass f32 to f64 param

    // §5 sltof: i64 → f64
    let v5_i64: i64 = 7;
    let r5: f64 = v5_i64;        // sltof  → 7.0f64

    // §6 swtof: i32 → f64
    let v6_i32: i32 = id_i32(9);
    let r6: f64 = v6_i32;        // swtof  → 9.0f64

    // 评分:每 op 命中 +1/2/4/8/16/32
    let r3i: i32 = r3 as i32;           // 2
    let r4i: i32 = v4 as i32;           // 2
    let r5i: i32 = r5 as i32;           // 7
    let r6i: i32 = r6 as i32;           // 9

    let mut score: i32 = 0;
    if r1 == 3 { score = score + 1; }
    if r2 == 3 { score = score + 2; }
    if r3i == 2 { score = score + 4; }
    if r4i == 2 { score = score + 8; }
    if r5i == 7 { score = score + 16; }
    if r6i == 9 { score = score + 32; }

    // 期望 EXIT = 63 (1+2+4+8+16+32)
    //
    // EXPECT 推导(6 个比较全在 `as i32` 之后的 i32 上,不受 W-109 浮点比较缺陷影响):
    //   §1 dtosi   trunc(3.7)          = 3  → +1
    //   §2 stosi   trunc(3.7f32)       = 3  → +2
    //   §3 truncd  trunc(2.5f32)       = 2  → +4
    //   §4 exts    2.5f32 → 2.5f64 → 2    → +8
    //   §5 sltof   7i64 → 7.0 → 7         → +16
    //   §6 swtof   9i32 → 9.0 → 9         → +32
    //   EXIT = 1+2+4+8+16+32 = 63
    return score;
}

// spec_int_to_float.jhyy — spec §4.3:整数 → 浮点 的**全部 8 个**组合
//
// 2026-10-26(W-149 真修):整数→浮点转换的矩阵门。
//
// 修前的症状(2026-10-26 实测,失败位掩码 = 234 = 2|8|32|64|128):
//
//   ① **u64 → f64 走的是有符号转换** —— 前端一律发 `sltof`(i64→f64 有符号)
//      ⇒ 值 ≥ 2^63 变**负数**。
//      (后端的 `ultof`(u64→f64)早就写好了,W-146 还把它的算法修对了,
//       但前端从来没发过它 ⇒ 那条修复对 u64→f64 是**死代码**。)
//
//   ② **f32 目标拿到的是 f64** —— 后端四个 tof op 里只有 `swtof` 会按目标槽
//      在 cvtsi2ss/cvtsi2sd 之间切,另外三个恒产 f64
//      (见 compiler/src0/codegen_amd64_state.jhyy 的 ILTOK_* 注释)
//      ⇒ 旧表给 f32 目标发 `ultof`/`uwtof` ⇒ **f64 的位模式塞进 f32 槽**
//      ⇒ 读出来是垃圾。⇒ i32→f32 / u32→f32 / i64→f32 / u64→f32 **四个全错**。
//
// 修法(compiler/src0/codegen.jhyy 的 cg_convert_arg):
//   · 按**源类型的 prim** 判符号性 ⇒ 无符号源发 `ultof`(u64→f64)/ `uwtof`(u32→f64)
//   · f32 目标统一「先转 f64,再 truncd」(那四个 op 在本后端恒产 f64)
//
// ⚠ `18446744073709551615u64` 字面量本身有**已知限制**(会被解析成 i64 max,
//   见 spec_int_suffix_i16_u64.jhyy 头部注释)⇒ ≥ 2^63 的 u64 值一律**运行时算**。
// ⚠ f32 尾数只有 24 位 ⇒ 2^24 以上的整数在 f32 里**不精确** ⇒ u32→f32 用
//   2^24 断言(4000000000 在 f32 里会被舍入 ⇒ 拿它断言会误判)。
//
// EXPECT: 0
fn main_jhyy() -> i32 {
    let mut fails: i32 = 0;

    // ── i32 → f64 ──
    let a1: i32 = -5;
    let b1: f64 = a1;
    if b1 != -5.0 { fails = fails + 1; }

    // ── i32 → f32 ──
    let a2: i32 = -5;
    let b2: f32 = a2 as f32;
    if b2 != -5.0 { fails = fails + 2; }

    // ── u32 → f64(4000000000 在 f64 里精确)──
    let a3: u32 = 4000000000u32;
    let b3: f64 = a3;
    if b3 != 4000000000.0 { fails = fails + 4; }

    // ── u32 → f32(2^24 = 16777216 是 f32 里精确的整数)──
    let a4: u32 = 16777216u32;
    let b4: f32 = a4 as f32;
    if b4 != 16777216.0 { fails = fails + 8; }

    // ── i64 → f64 ──
    let a5: i64 = -5i64;
    let b5: f64 = a5;
    if b5 != -5.0 { fails = fails + 16; }

    // ── i64 → f32 ──
    let a6: i64 = -5i64;
    let b6: f32 = a6 as f32;
    if b6 != -5.0 { fails = fails + 32; }

    // ── u64 → f64(2^63,运行时算)──
    let a7: u64 = 9223372036854775807u64 + 1u64;
    let b7: f64 = a7;
    if b7 != 9223372036854775808.0 { fails = fails + 64; }

    // ── u64 → f32(2^63 是 f32 里精确的整数)──
    let a8: u64 = 9223372036854775807u64 + 1u64;
    let b8: f32 = a8 as f32;
    if b8 != 9223372036854775808.0 { fails = fails + 128; }

    // ── f32 → f64 回读(exts 路径;顺带覆盖 f32 槽的读回)──
    let c1: f32 = 1.5;
    let c2: f64 = c1;
    if c2 != 1.5 { fails = fails + 256; }

    // ── 窄宽度(u8/u16/i8/i16)→ 浮点 ──
    //
    // 这四条走的是 **'w' 槽** 那条路(值是 loadub/loaduh 零扩展进 4 字节槽)
    // ⇒ 发的是 `swtof` / **`uwtof`** —— 而 `uwtof` 在 W-145 之前是**死 op**
    // (IL lexer 没有 'u' 分支)⇒ 这几条是 W-145 的**载荷覆盖**。
    let d1: u8 = 255u8;
    let e1: f64 = d1;
    if e1 != 255.0 { fails = fails + 512; }

    let d2: u16 = 65535u16;
    let e2: f64 = d2;
    if e2 != 65535.0 { fails = fails + 1024; }

    let d3: i8 = -5i8;
    let e3: f64 = d3;
    if e3 != -5.0 { fails = fails + 2048; }

    let d4: i16 = -5i16;
    let e4: f64 = d4;
    if e4 != -5.0 { fails = fails + 4096; }

    let d5: u8 = 255u8;
    let e5: f32 = d5 as f32;
    let e5d: f64 = e5;
    if e5d != 255.0 { fails = fails + 8192; }

    let d6: u16 = 65535u16;
    let e6: f32 = d6 as f32;
    let e6d: f64 = e6;
    if e6d != 65535.0 { fails = fails + 16384; }

    return fails;
}

// spec_literals_types.jhyy — spec §2.5 / §2.1 / §4.3:字面量后缀与类型边界
//
// 覆盖缺口(2026-10-26 lang-spec 覆盖审计):
//   ① §2.5「后缀:`f32` / `f64` / `f`(= f64)」—— `f` 这个别名**零覆盖**
//      (int_suffix.jhyy 覆盖了整数后缀,但浮点的 `f` 别名没有);
//   ② §2.1 `bool` 占 1 字节、字面量只有 true/false —— 作为**类型**零覆盖
//      (既有测试只在 sizeof(bool) 里出现过);
//   ③ §4.3 的**整数 ↔ 指针**与**整数 → 浮点** —— 零覆盖。
//   (浮点 ↔ 指针那一对与 spec 不符,已拆成 XFAIL 门 spec_ptr_float_cast.jhyy)
//
// EXPECT: 0
fn main_jhyy() -> i32 {
    let mut fails: i32 = 0;

    // ── ① 浮点后缀:f32 / f64 / f(= f64)──
    let a: f32 = 2.5f32;
    if a as i32 != 2 { fails = fails + 1; }
    let b: f64 = 2.5f64;
    if b as i32 != 2 { fails = fails + 1; }
    // `f` 是 f64 的别名
    let c: f64 = 2.5f;
    if c as i32 != 2 { fails = fails + 1; }
    // `f` 后缀的值与 f64 后缀的值一致
    let d: f64 = 7.25f;
    let e: f64 = 7.25f64;
    if d != e { fails = fails + 1; }

    // ── ② bool 类型 ──
    let t: bool = true;
    let f: bool = false;
    if t == f { fails = fails + 1; }
    // bool 只能进条件,不能混进 i32 算术(那是设计如此,这里只验条件用法)
    let mut r: i32 = 0;
    if t { r = 1; }
    if r != 1 { fails = fails + 1; }
    let mut r2: i32 = 0;
    if f { r2 = 1; }
    if r2 != 0 { fails = fails + 1; }

    // ── ③ 整数 ↔ 指针(地址原样保留)──
    let addr: i64 = 0x41424344 as i64;
    let p: *i32 = addr as *i32;
    if (p as i64) != 0x41424344 as i64 { fails = fails + 1; }
    if (p as i64) != addr { fails = fails + 1; }

    // ── ④ 整数 → 浮点(数值转换)──
    let one: i64 = 1;
    let onef: f64 = one;
    if onef != 1.0 { fails = fails + 1; }

    // ⚠️ 浮点 ↔ 指针(spec §4.3 写的是「按位重解释」)的现状**与 spec 不符**,
    //   已单独拆成 XFAIL 门 `spec_ptr_float_cast.jhyy`(台账 W-143)——
    //   实测:浮点→指针走**数值截断**(1.5 → 1),指针→浮点给 **0**
    //   (既不是地址也不是位模式)。本用例只覆盖已定义正确的部分。

    return fails;
}

// spec_ptr_float_cast.jhyy — spec §4.3:浮点 ↔ 指针的转换语义
//
// 2026-10-26:这是 lang-spec 覆盖审计挖出的**语义缺口**(台账 W-143)的回归门。
// XFAIL 标记已摘(留着会让 regress 报 XPASS)。
//
// 语义(用户 2026-10-26 拍板):**数值转换** —— 不是位重解释、不是解引用。
//   · `x as *T` ≡ **饱和**转成 64 位无符号整数 → 当地址
//     (NaN → 0;x < 0 → 0;x ≥ 2^64 → u64::MAX;区间内向 0 截断)
//   · `p as f64` ≡ 地址当 64 位**无符号**整数 → 数值转浮点
//     (整数→浮点是 roundTiesToEven,只可能丢精度;**不涉及饱和** ⇒ 不对称化)
//
// 修前的症状:浮点→指针走裸 cvttsd2si(数值截断);指针→浮点**一条指令都不发**
// ⇒ 结果 temp 的 qbe_type 仍是 'l' ⇒ 流进 f64 形参时 caller 放整数寄存器 /
// callee 读 XMM ⇒ **ABI 寄存器类错配**。
//
// EXPECT: 0
fn main_jhyy() -> i32 {
    let mut fails: i32 = 0;

    // ① 判定性往返:1.0 → 指针 → f64 ⇒ 1.0
    let one: f64 = 1.0;
    let p1: *i64 = one as *i64;
    let back1: f64 = p1;
    if back1 != 1.0 { fails = fails + 1; }

    // ② 区间内:1.5 → 1(向 0 截断)
    let half: f64 = 1.5;
    let p2: *i64 = half as *i64;
    if (p2 as i64) != 1 { fails = fails + 1; }

    // ③ 负数 → 0(饱和到下界)
    let neg: f64 = 0.0 - 1.5;
    let p3: *i64 = neg as *i64;
    if (p3 as i64) != 0 { fails = fails + 1; }

    // ④ NaN → 0(饱和)
    let zero: f64 = 0.0;
    let nan: f64 = zero / zero;
    let p4: *i64 = nan as *i64;
    if (p4 as i64) != 0 { fails = fails + 1; }

    // ⑤ 指针 → 浮点:地址当 u64 的数值(不是 0,也不是位重解释)
    let x: i64 = 12345;
    let q: *i64 = &x;
    let as_f: f64 = q;
    if as_f <= 0.0 { fails = fails + 1; }
    // 同一个地址的两种读法应一致(u64 → f64)
    let addr: u64 = q as u64;
    let d: f64 = as_f - (addr);
    if d > 1.0 { fails = fails + 1; }
    if d < 0.0 - 1.0 { fails = fails + 1; }

    return fails;
}

