type Option = enum { Some(i32, i32), None }

fn unwrap_or(opt: Option, default: i32) -> i32 {
    match opt {
        Option::Some(_) => 1,
        Option::None    => default,
    }
}

fn unwrap_or_short(opt: Option, default: i32) -> i32 {
    match opt {
        Some(_) => 1,
        None    => default,
    }
}

fn main_jhyy() -> i32 {
